mapper.select:
SELECT d.id AS device_id, current_type.product_type_code, product_type.display_name, product_type.enabled, current_type.source_version, current_type.resolution_status, product_type.sync_status, product_type.synced_at AS last_successful_sync_time FROM ast_device d LEFT JOIN ast_device_current_product_type current_type ON current_type.tenant_id = d.tenant_id AND current_type.device_id = d.id AND current_type.current_marker = 1 AND current_type.deleted = b'0' LEFT JOIN ast_product_type product_type ON product_type.tenant_id = current_type.tenant_id AND product_type.id = current_type.product_type_id AND product_type.deleted = b'0' AND product_type.type_code = current_type.product_type_code WHERE d.tenant_id = #{query.tenantId} AND d.deleted = b'0' AND d.id IN
#{deviceId}
AND ( d.project_id IN
#{projectId}
OR EXISTS ( SELECT 1 FROM ast_device_project_relationship relation WHERE relation.tenant_id = d.tenant_id AND relation.device_sn = d.sn AND relation.project_id IN
#{projectId}
AND relation.effective_from <= #{query.effectiveAt} AND (relation.effective_to IS NULL OR relation.effective_to > #{query.effectiveAt}) AND relation.deleted = b'0' ) ) ORDER BY d.id
